import{_ as i,l as s,o as e,c as l,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"TPM 与度量启动","description":"","frontmatter":{"title":"TPM 与度量启动","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tpm-measured-boot.md","filePath":"cs/tpm-measured-boot.md","lastUpdated":1789023840000}'),P={name:"cs/tpm-measured-boot.md"};function m(u,a,h,T,_,C){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="tpm-与度量启动" tabindex="-1">TPM 与度量启动 <a class="header-anchor" href="#tpm-与度量启动" aria-label="Permalink to &quot;TPM 与度量启动&quot;">​</a></h1><div class="epigraph"><p>度量启动把引导组件的哈希扩展进 TPM 的 PCR：密封密钥只在 PCR 符合预期时解开，从而把「启动了预期的代码」接到密钥。</p><footer>—— 据 TCG 对 PCR 扩展的说明；Linux IMA/EVM 与 systemd-cryptenroll 实践</footer></div><p><a href="/cs/secure-boot">安全启动</a> 是「验签放行」。度量是 <strong>记录实际跑了什么</strong>。缺口是 TPM PCR、密封、与 <a href="/cs/dm-crypt">dm-crypt</a> 解封。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PCR 只能 extend 不能随意写。启动器把 grub、kernel、cmdline 哈希进去。缺口：策略 PCR 集合；远程证明 quote；IMA 继续度量运行时文件。本课不把 TPM 2.0 命令表当作业。</p><p><span class="marginnote">更新内核会改 PCR，未更新策略则盘解不开——这是特性不是 bug。对象是硬件信任根。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>boot 路径 extend → 用户 <code>unseal</code> 密钥 → 开 LUKS。对照 cap：运行时特权。对照 audit：PCR 在芯片里更抗篡改。对照 KPTI：无关。</p>',8)),(e(),n(c,null,{default:r(()=>[p(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20COMP%5B%22%E5%BC%95%E5%AF%BC%E7%BB%84%E4%BB%B6%22%5D%20--%3E%20HASH%5B%22%E5%93%88%E5%B8%8C%22%5D%0A%20%20HASH%20--%3E%20PCR%5B%22TPM%20extend%22%5D%0A%20%20KEY%5B%22%E5%AF%86%E5%B0%81%E5%AF%86%E9%92%A5%22%5D%20--%3E%20UNSEAL%5B%22PCR%20%E5%8C%B9%E9%85%8D%E6%89%8D%E9%87%8A%E6%94%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TPM 把启动完整性变成密钥释放条件，使冷启动攻击更难（不完美）。不要写成军用认证。与 <a href="/cs/memory-hotplug">热插拔</a> 无关。与网络远程证明是同一 PCR 的出口。</p><p>PCR 预测错误是部署第一痛。</p><p>实现上：PCR 扩展不可回退，升级内核必须同时更新密封策略。quote 把 PCR 签给远端，但要验 TPM 密钥链。IMA 把度量从启动延续到运行时文件。 读法上只引用<a href="/cs/secure-boot">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>TPM 与度量启动</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入全部 NV index。不保证虚拟 TPM 与硬件同等。下一课根文件系统如何切进来：initramfs 与 pivot。</p><p>版本字段会变，课序钉的是机制对象「TPM 与度量启动」，不是某一主线内核的结构体名。 后课默认：PCR 可密封磁盘密钥。早期用户空间与切换根，下一课 initramfs。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>度量启动把哈希扩展进 PCR。</li><li>密封把密钥绑到预期启动状态。</li><li>initramfs/pivot 是下一课。</li><li>出处：TCG；IMA；systemd TPM；LUKS。</li></ul>',11))])}const M=i(P,[["render",m]]);export{E as __pageData,M as default};
